const WebSocket = require('ws');
const http = require('http');
const crypto = require('crypto');

const server = http.createServer();
const wss = new WebSocket.Server({ server });

// In-memory store for contract event messages
const eventLog = [];
const MAX_LOG_SIZE = 1000;

// HTML entity encoding map
const ENCODE_MAP = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#x27;'
};

function encodeHTML(str) {
  return String(str).replace(/[&<>"']/g, (ch) => ENCODE_MAP[ch]);
}

// Solidity event ABI decoder (simplified)
function decodeEventData(rawHex) {
  // Strip 0x prefix if present
  const hex = rawHex.startsWith('0x') ? rawHex.slice(2) : rawHex;
  // Decode as UTF-8 string from hex
  const bytes = Buffer.from(hex, 'hex');
  return bytes.toString('utf8');
}

// Normalize unicode to prevent homoglyph attacks
function normalizeText(text) {
  return text.normalize('NFC');
}

// Content security filter for stored messages
function sanitizeForStorage(input) {
  const normalized = normalizeText(input);
  // Apply HTML encoding for safe rendering
  const encoded = encodeHTML(normalized);
  return encoded;
}

// Render stored event for client consumption
function renderEventMessage(event) {
  const timestamp = new Date(event.timestamp).toISOString();
  // Build HTML fragment for the event display
  const html = `<div class="event" data-id="${event.id}">`
    + `<span class="time">${timestamp}</span>`
    + `<span class="addr">${event.address}</span>`
    + `<span class="msg">${event.message}</span>`
    + `</div>`;
  return html;
}

function processIncomingEvent(data) {
  try {
    const parsed = JSON.parse(data);

    if (!parsed.type || !parsed.payload) {
      return { error: 'Invalid message format' };
    }

    if (parsed.type === 'solidity_event') {
      const { contractAddress, eventData, encoding } = parsed.payload;

      // Validate contract address format
      if (!/^0x[0-9a-fA-F]{40}$/.test(contractAddress)) {
        return { error: 'Invalid contract address' };
      }

      let messageContent;

      if (encoding === 'hex') {
        // Decode from hex-encoded event data (e.g., from eth_getLogs)
        messageContent = decodeEventData(eventData);
      } else if (encoding === 'utf8') {
        messageContent = eventData;
      } else {
        return { error: 'Unsupported encoding' };
      }

      // Sanitize the decoded content before storage
      const sanitized = sanitizeForStorage(messageContent);

      const eventRecord = {
        id: crypto.randomUUID(),
        address: encodeHTML(contractAddress),
        message: sanitized,
        timestamp: Date.now(),
        rawEncoding: encoding
      };

      eventLog.push(eventRecord);
      if (eventLog.length > MAX_LOG_SIZE) {
        eventLog.shift();
      }

      return { success: true, event: eventRecord };
    }

    if (parsed.type === 'get_events') {
      const rendered = eventLog.map(renderEventMessage);
      return { success: true, html: rendered.join('') };
    }

    if (parsed.type === 'get_event_raw') {
      const { eventId } = parsed.payload;
      const found = eventLog.find(e => e.id === eventId);
      if (!found) return { error: 'Event not found' };
      // Return raw stored data for re-processing by client
      // Client may need original for signature verification
      return { success: true, event: found };
    }

    if (parsed.type === 'replay_event') {
      const { eventId, format } = parsed.payload;
      const found = eventLog.find(e => e.id === eventId);
      if (!found) return { error: 'Event not found' };

      if (format === 'html') {
        return { success: true, html: renderEventMessage(found) };
      } else if (format === 'raw_decoded') {
        // For clients that need to re-verify the original message
        // Decode the stored HTML entities back to original text
        const decoded = found.message
          .replace(/&amp;/g, '&')
          .replace(/&lt;/g, '<')
          .replace(/&gt;/g, '>')
          .replace(/&quot;/g, '"')
          .replace(/&#x27;/g, "'");
        return { success: true, message: decoded, address: found.address };
      }
      return { error: 'Unknown format' };
    }

    return { error: 'Unknown message type' };
  } catch (e) {
    return { error: 'Parse error: ' + e.message };
  }
}

wss.on('connection', (ws) => {
  ws.on('message', (data) => {
    const result = processIncomingEvent(data.toString());
    ws.send(JSON.stringify(result));

    // Broadcast new events to all connected clients
    if (result.success && result.event) {
      const broadcast = JSON.stringify({
        type: 'new_event',
        html: renderEventMessage(result.event)
      });
      wss.clients.forEach((client) => {
        if (client !== ws && client.readyState === WebSocket.OPEN) {
          client.send(broadcast);
        }
      });
    }
  });
});

// Graceful shutdown
let isShuttingDown = false;

function gracefulShutdown() {
  if (isShuttingDown) return;
  isShuttingDown = true;

  console.log('Shutting down gracefully...');

  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(JSON.stringify({ type: 'server_shutdown' }));
      client.close(1001, 'Server shutting down');
    }
  });

  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 5000);
}

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

const PORT = process.env.PORT || 8080;
server.listen(PORT, () => {
  console.log(`WebSocket server listening on port ${PORT}`);
});
